func structuredEntryKindLabel(value string) string {
	switch value {
	case "REST":
		return "Descanso"
	case "COMPETITION":
		return "Competição"
	case "LOGISTICS":
		return "Logística"
	default:
		return "Treino"
	}
}
func structuredModalityLabel(value string) string {
	switch value {
	case "WATER":
		return "Água"
	case "GYM":
		return "Ginásio"
	case "RUN":
		return "Corrida"
	case "BIKE":
		return "Bicicleta"
	case "ERGOMETER":
		return "Ergómetro"
	case "FLEXIBILITY":
		return "Flexibilidade e mobilidade"
	case "SPORTS_GAMES":
		return "Jogos desportivos"
	default:
		return "Outra"
	}
}
func structuredModalitiesLabel(values []string) string {
	labels := make([]string, 0, len(values))
	for _, value := range values {
		labels = append(labels, structuredModalityLabel(value))
	}
	return strings.Join(labels, " + ")
}
